-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_MARTS_CORE, target ORDERS.
-- WARNING: EXP_CUSTOMER_ORDER_NUM.CUSTOMER_ORDER_NUMBER set to NULL: v_ORDER_SEQUENCE reads the previous row's value of v_ORDER_SEQUENCE (stateful variable port). Informatica expression: v_ORDER_SEQUENCE

with

sq_stg_supplies2 as (
    -- Source Qualifier SQ_STG_SUPPLIES2
    select
        stg_supplies2.supply_id,
        stg_supplies2.supply_name,
        stg_supplies2.supply_cost_cents,
        stg_supplies2.supply_cost,
        stg_supplies2.is_perishable,
        stg_supplies2.product_id
    from {{ ref('stg_supplies') }} as stg_supplies2
),

agg_supplies_by_product2 as (
    -- Aggregator AGG_SUPPLIES_BY_PRODUCT2
    select
        sq_stg_supplies2.product_id,
        sum(sq_stg_supplies2.supply_cost) as supply_cost_per_product
    from sq_stg_supplies2
    group by sq_stg_supplies2.product_id
),

sq_stg_order_items1 as (
    -- Source Qualifier SQ_STG_ORDER_ITEMS1
    select
        stg_order_items1.order_item_id,
        stg_order_items1.order_id,
        stg_order_items1.product_id
    from {{ ref('stg_order_items') }} as stg_order_items1
),

sq_stg_products2 as (
    -- Source Qualifier SQ_STG_PRODUCTS2
    select
        stg_products2.product_id,
        stg_products2.product_name,
        stg_products2.product_type,
        stg_products2.product_price_cents,
        stg_products2.product_price,
        stg_products2.product_description,
        stg_products2.is_food_item,
        stg_products2.is_drink_item
    from {{ ref('stg_products') }} as stg_products2
),

jnr_items_products as (
    -- Joiner JNR_ITEMS_PRODUCTS
    -- Normal Join (master sq_stg_order_items1, detail sq_stg_products2)
    select
        sq_stg_order_items1.order_id,
        sq_stg_order_items1.order_item_id,
        sq_stg_products2.product_id,
        sq_stg_products2.product_price,
        sq_stg_products2.is_food_item,
        sq_stg_products2.is_drink_item
    from sq_stg_products2
        inner join sq_stg_order_items1
            on sq_stg_order_items1.product_id = sq_stg_products2.product_id
),

jnr_items_supplies as (
    -- Joiner JNR_ITEMS_SUPPLIES
    -- Master Outer Join (master jnr_items_products, detail agg_supplies_by_product2)
    select
        jnr_items_products.order_id,
        jnr_items_products.order_item_id,
        jnr_items_products.product_id,
        jnr_items_products.product_price,
        jnr_items_products.is_food_item,
        jnr_items_products.is_drink_item,
        agg_supplies_by_product2.supply_cost_per_product
    from agg_supplies_by_product2
        left join jnr_items_products
            on jnr_items_products.product_id = agg_supplies_by_product2.product_id
),

agg_items_by_order as (
    -- Aggregator AGG_ITEMS_BY_ORDER
    select
        jnr_items_supplies.order_id,
        count(*) as items_count,
        sum(jnr_items_supplies.product_price) as order_items_subtotal,
        sum(coalesce(jnr_items_supplies.supply_cost_per_product, 0)) as order_cost,
        max(jnr_items_supplies.is_food_item) as has_food_items,
        max(jnr_items_supplies.is_drink_item) as has_drink_items
    from jnr_items_supplies
    group by jnr_items_supplies.order_id
),

sq_stg_orders1 as (
    -- Source Qualifier SQ_STG_ORDERS1
    select
        stg_orders1.order_id,
        stg_orders1.customer_id,
        stg_orders1.location_id,
        stg_orders1.ordered_at_day,
        stg_orders1.subtotal_cents,
        stg_orders1.tax_paid_cents,
        stg_orders1.order_total_cents,
        stg_orders1.subtotal,
        stg_orders1.tax_paid,
        stg_orders1.order_total
    from {{ ref('stg_orders') }} as stg_orders1
),

jnr_orders_items_agg as (
    -- Joiner JNR_ORDERS_ITEMS_AGG
    -- Master Outer Join (master sq_stg_orders1, detail agg_items_by_order)
    select
        agg_items_by_order.order_id,
        sq_stg_orders1.customer_id,
        sq_stg_orders1.location_id,
        sq_stg_orders1.ordered_at_day,
        sq_stg_orders1.subtotal_cents,
        sq_stg_orders1.tax_paid_cents,
        sq_stg_orders1.order_total_cents,
        sq_stg_orders1.subtotal,
        sq_stg_orders1.tax_paid,
        sq_stg_orders1.order_total,
        agg_items_by_order.items_count,
        agg_items_by_order.order_items_subtotal,
        agg_items_by_order.order_cost,
        agg_items_by_order.has_food_items,
        agg_items_by_order.has_drink_items
    from agg_items_by_order
        left join sq_stg_orders1
            on sq_stg_orders1.order_id = agg_items_by_order.order_id
),

exp_orders_calc as (
    -- Expression EXP_ORDERS_CALC
    select
        jnr_orders_items_agg.order_id,
        jnr_orders_items_agg.customer_id,
        jnr_orders_items_agg.location_id,
        jnr_orders_items_agg.ordered_at_day,
        jnr_orders_items_agg.subtotal_cents / 100 as subtotal_recal,
        jnr_orders_items_agg.tax_paid_cents / 100 as tax_paid_recal,
        jnr_orders_items_agg.order_total_cents / 100 as order_total_recal,
        coalesce(jnr_orders_items_agg.order_items_subtotal, 0) as order_items_subtotal_cl,
        coalesce(jnr_orders_items_agg.order_cost, 0) as order_cost_cl,
        coalesce(jnr_orders_items_agg.has_food_items, 0) as has_food_items_cl,
        coalesce(jnr_orders_items_agg.has_drink_items, 0) as has_drink_items_cl
    from jnr_orders_items_agg
),

srt_by_customer as (
    -- Sorter SRT_BY_CUSTOMER
    -- sort order dropped: a table or view has no row order
    select
        exp_orders_calc.customer_id,
        exp_orders_calc.location_id,
        exp_orders_calc.ordered_at_day,
        exp_orders_calc.order_id,
        exp_orders_calc.subtotal_recal,
        exp_orders_calc.tax_paid_recal,
        exp_orders_calc.order_total_recal,
        exp_orders_calc.order_items_subtotal_cl,
        exp_orders_calc.order_cost_cl,
        exp_orders_calc.has_food_items_cl,
        exp_orders_calc.has_drink_items_cl
    from exp_orders_calc
),

exp_customer_order_num as (
    -- Expression EXP_CUSTOMER_ORDER_NUM
    select
        srt_by_customer.order_id,
        srt_by_customer.customer_id,
        srt_by_customer.location_id,
        srt_by_customer.ordered_at_day,
        srt_by_customer.subtotal_recal as subtotal,
        srt_by_customer.tax_paid_recal as tax_paid,
        srt_by_customer.order_total_recal as order_total,
        srt_by_customer.order_items_subtotal_cl as order_items_subtotal,
        srt_by_customer.order_cost_cl as order_cost,
        srt_by_customer.has_food_items_cl as has_food_items,
        srt_by_customer.has_drink_items_cl as has_drink_items,
        null /* UNSUPPORTED: see warning above */ as customer_order_number
    from srt_by_customer
)

select
    exp_customer_order_num.order_id,
    exp_customer_order_num.customer_id,
    exp_customer_order_num.location_id,
    exp_customer_order_num.ordered_at_day,
    exp_customer_order_num.subtotal,
    exp_customer_order_num.tax_paid,
    exp_customer_order_num.order_total,
    exp_customer_order_num.order_items_subtotal,
    exp_customer_order_num.order_cost,
    exp_customer_order_num.has_food_items,
    exp_customer_order_num.has_drink_items,
    exp_customer_order_num.customer_order_number
from exp_customer_order_num
